/**
 * 浏览器管理器
 * 负责管理浏览器实例和锁机制
 */

import type { Browser, Page } from 'playwright';
import { createMobileBrowser } from '../index';
import { DatabaseAdapter } from '../database/database-adapter';
import type { BrowserOptions } from '../configurators/context-configurator';

interface BrowserSession {
  browser: Browser;
  page: Page;
  deviceId: string;
  deviceName: string;
  startedAt: Date;
}

class BrowserManager {
  private static instance: BrowserManager;
  private currentSession: BrowserSession | null = null;
  private lock: boolean = false;
  private db: DatabaseAdapter;

  private constructor() {
    this.db = new DatabaseAdapter();
  }

  static getInstance(): BrowserManager {
    if (!BrowserManager.instance) {
      BrowserManager.instance = new BrowserManager();
    }
    return BrowserManager.instance;
  }

  /**
   * 尝试获取锁
   * @returns 是否成功获取锁
   */
  tryLock(): boolean {
    if (this.lock) {
      return false;
    }
    this.lock = true;
    return true;
  }

  /**
   * 释放锁
   */
  releaseLock(): void {
    this.lock = false;
  }

  /**
   * 检查是否有正在运行的浏览器
   */
  hasActiveSession(): boolean {
    return this.lock && this.currentSession !== null;
  }

  /**
   * 获取当前会话信息
   */
  getCurrentSession(): BrowserSession | null {
    return this.currentSession;
  }

  /**
   * 从数据库随机选择一个设备
   */
  private async getRandomDevice(): Promise<{ id: string; name: string }> {
    const devices = await this.db.getAllDevices();
    if (devices.length === 0) {
      throw new Error('数据库中没有可用设备');
    }
    const randomIndex = Math.floor(Math.random() * devices.length);
    const device = devices[randomIndex];
    return {
      id: String(device.id),
      name: device.name,
    };
  }

  /**
   * 从语言列表中随机选择语言
   */
  private getRandomLanguage(languages: string[]): string {
    if (languages.length === 0) {
      return 'en-US';
    }
    const randomIndex = Math.floor(Math.random() * languages.length);
    return languages[randomIndex];
  }

  /**
   * 启动浏览器并访问指定网址
   * @param url 目标网址
   * @param referer Referer 头
   * @param proxy 代理配置（可选）
   * @param languageRotation 语言轮询列表（可选）
   */
  async startBrowser(
    url: string,
    referer: string,
    proxy?: string,
    languageRotation?: string[]
  ): Promise<void> {
    // 检查锁
    if (!this.tryLock()) {
      throw new Error('上一次请求正在处理中，请稍后再试');
    }

    try {
      // 随机选择设备
      const { id: deviceId, name: deviceName } = await this.getRandomDevice();

      // 准备语言轮询列表
      const languages = languageRotation || ['ja', 'ja-JP'];
      const selectedLanguage = this.getRandomLanguage(languages);

      // 配置浏览器选项
      const browserOptions: BrowserOptions = {
        headless: false,
        launchOptions: {
          headless: false,
        },
        languageRotation: languages,
        ...(proxy && { proxy }),
      };

      // 创建浏览器
      const { browser, page } = await createMobileBrowser(deviceId, browserOptions);

      // 设置 Referer
      await page.setExtraHTTPHeaders({
        Referer: referer,
      });

      // 访问目标网址
      await page.goto(url, {
        waitUntil: 'networkidle',
        timeout: 30000,
      });

      // 保存会话信息
      this.currentSession = {
        browser,
        page,
        deviceId,
        deviceName,
        startedAt: new Date(),
      };

      console.log(`浏览器已启动: 设备=${deviceName}, 语言=${selectedLanguage}, URL=${url}`);
    } catch (error) {
      // 如果出错，释放锁
      this.releaseLock();
      throw error;
    }
  }

  /**
   * 关闭当前浏览器会话
   */
  async closeBrowser(): Promise<void> {
    if (this.currentSession) {
      try {
        await this.currentSession.browser.close();
      } catch (error) {
        console.error('关闭浏览器时出错:', error);
      }
      this.currentSession = null;
    }
    this.releaseLock();
  }

  /**
   * 获取浏览器状态
   */
  getStatus(): {
    isRunning: boolean;
    deviceName?: string;
    startedAt?: Date;
  } {
    if (this.currentSession) {
      return {
        isRunning: true,
        deviceName: this.currentSession.deviceName,
        startedAt: this.currentSession.startedAt,
      };
    }
    return {
      isRunning: false,
    };
  }
}

export const browserManager = BrowserManager.getInstance();

